function evaluate(input, helpers) {
  var action = input.action || {};
  var kind = action.canonicalKind;
  var params = action.paramsSummary;
  var cmd = (params && typeof params.command === 'string') ? params.command : '';
  var isCommit = kind === 'execute' && /\bgit\b[^&;|]*\bcommit\b/.test(cmd);
  var isStateChange = kind === 'write' || kind === 'execute' || kind === 'agent';

  // Trusted design-approval fact only; params text and history are never proof
  // of approval, and an absent/unknown fact is never treated as approval.
  var facts = (input.context && input.context.facts) ? input.context.facts : {};
  var gate = facts.designGate;
  var resolution = (gate && typeof gate.resolution === 'string') ? gate.resolution : 'unknown';
  var revoked = !!(gate && gate.revoked === true);
  if (revoked) { resolution = 'not_approved'; }

  var validBinding = !!gate &&
    typeof gate.sourceRef === 'string' && gate.sourceRef.length > 0 &&
    typeof gate.revision === 'number' && gate.revision > 0 &&
    gate.taskRef === gate.decisionTaskRef &&
    gate.specDigest === gate.decisionSpecDigest &&
    gate.scopeRef === gate.decisionScopeRef;

  if (!validBinding || resolution === 'unknown') {
    // Unknown/stale/mismatched is NOT an enforceable denial for general
    // actions: stay out of the way (the pipeline suspends enforcement then).
    // Only an uncommitted non-simple commit (the Owner-labelled negative
    // pattern) is held, since nothing in the input establishes approval.
    if (isCommit) {
      return { decision: 'block', matched: true, reason: 'committing a non-simple change without a resolvable Owner design approval fact (designGate unavailable/unknown); deliver SPEC and obtain explicit design confirmation first' };
    }
    return { decision: 'allow', matched: false, reason: 'designGate fact unknown/stale/mismatched; gate not enforceable for this action' };
  }

  if (resolution === 'approved' || resolution === 'not_required') {
    return { decision: 'allow', matched: true, reason: 'design gate resolution is ' + resolution + ' for this action' };
  }

  // resolution === 'not_approved' with a valid binding: the host already
  // resolved this action as inside the declared approval scope.
  if (isStateChange) {
    return {
      decision: 'block',
      matched: true,
      reason: 'non-simple high-cost change without explicit Owner design approval (designGate=not_approved); deliver SPEC with call chain, I/O, cost, failure handling, acceptance and rollback, and obtain Owner design confirmation before coding/committing'
    };
  }
  return { decision: 'allow', matched: false, reason: 'read-only action kind outside the design-approval gate' };
}
